  PRIMARY KEY (revision_uuid, detector)
) STRICT;
CREATE TABLE icfactor_reference (
  revision_uuid TEXT NOT NULL CHECK (length(revision_uuid) = 36),
  detector TEXT NOT NULL,
  ordinal INTEGER NOT NULL,
  ref_analysis_uuid TEXT REFERENCES analysis CHECK (length(ref_analysis_uuid) = 36),
  record_id TEXT,
  exclude INTEGER NOT NULL DEFAULT 0 CHECK (exclude IN (0, 1)),
  PRIMARY KEY (revision_uuid, detector, ordinal),
  FOREIGN KEY (revision_uuid, detector) REFERENCES icfactor_value
) STRICT;
CREATE TABLE signal_ref (
  revision_uuid TEXT NOT NULL REFERENCES revision CHECK (length(revision_uuid) = 36),
  series_kind TEXT NOT NULL CHECK (series_kind IN ('signal','baseline','sniff','whiff')),
  series_key TEXT NOT NULL,
  detector TEXT NOT NULL,
  blob_sha BLOB NOT NULL,
  n_points INTEGER,
  start_index INTEGER,
  end_index INTEGER,
  PRIMARY KEY (revision_uuid, series_kind, series_key)
) STRICT;
CREATE INDEX signal_ref_blob_ix ON signal_ref (blob_sha);
CREATE TABLE tag_value (
  revision_uuid TEXT NOT NULL PRIMARY KEY REFERENCES revision CHECK (length(revision_uuid) = 36),
  name TEXT NOT NULL,
  note TEXT,
  subgroup TEXT CHECK (json_valid(subgroup))
) STRICT;
CREATE TABLE annotation_value (
  revision_uuid TEXT NOT NULL PRIMARY KEY REFERENCES revision CHECK (length(revision_uuid) = 36),
  comment TEXT
) STRICT;
CREATE TABLE refpin_value (
  revision_uuid TEXT NOT NULL REFERENCES revision CHECK (length(revision_uuid) = 36),
  ref_object_uuid TEXT NOT NULL REFERENCES ref_object CHECK (length(ref_object_uuid) = 36),
  ref_revision_uuid TEXT NOT NULL REFERENCES revision CHECK (length(ref_revision_uuid) = 36),
  PRIMARY KEY (revision_uuid, ref_object_uuid)
) STRICT;
CREATE TABLE identity_value (
  revision_uuid TEXT NOT NULL PRIMARY KEY REFERENCES revision CHECK (length(revision_uuid) = 36),
  identifier_uuid TEXT NOT NULL REFERENCES identifier CHECK (length(identifier_uuid) = 36),
  aliquot INTEGER NOT NULL,
  increment INTEGER NOT NULL,
  reason TEXT NOT NULL
) STRICT;
CREATE TABLE cosmogenic_value (
  revision_uuid TEXT NOT NULL PRIMARY KEY REFERENCES revision CHECK (length(revision_uuid) = 36),
  doc TEXT NOT NULL CHECK (json_valid(doc))
) STRICT;
CREATE TABLE ia_value (
  revision_uuid TEXT NOT NULL PRIMARY KEY REFERENCES revision CHECK (length(revision_uuid) = 36),
  age REAL,
  age_err REAL,
  age_kind TEXT,
  kca REAL,
  kca_err REAL,
  mswd REAL,
  nanalyses INTEGER,
  doc TEXT NOT NULL CHECK (json_valid(doc))
) STRICT;
CREATE TABLE ia_member (
  revision_uuid TEXT NOT NULL REFERENCES ia_value CHECK (length(revision_uuid) = 36),
  analysis_uuid TEXT NOT NULL REFERENCES analysis CHECK (length(analysis_uuid) = 36),
  record_id TEXT,
  plateau_step INTEGER CHECK (plateau_step IN (0, 1)),
  tag TEXT,
  PRIMARY KEY (revision_uuid, analysis_uuid)
) STRICT;
CREATE TABLE flux_value (
  revision_uuid TEXT NOT NULL PRIMARY KEY REFERENCES revision CHECK (length(revision_uuid) = 36),
  j REAL,
  j_err REAL,
  mean_j REAL,
  mean_j_err REAL,
  mean_j_mswd REAL,
  position_jerr REAL,
  lambda_k_total REAL,
  lambda_k_total_err REAL,
  monitor_name TEXT,
  monitor_material TEXT,
  monitor_age REAL,
  monitor_age_err REAL,
  options TEXT CHECK (json_valid(options)),
  extra TEXT CHECK (json_valid(extra))
) STRICT;
CREATE TABLE flux_value_analysis (
  revision_uuid TEXT NOT NULL REFERENCES flux_value CHECK (length(revision_uuid) = 36),
  analysis_uuid TEXT CHECK (length(analysis_uuid) = 36),
  record_id TEXT NOT NULL,
  is_omitted INTEGER NOT NULL CHECK (is_omitted IN (0, 1)),
  PRIMARY KEY (revision_uuid, record_id)
) STRICT;
CREATE TABLE level_z_value (
  revision_uuid TEXT NOT NULL PRIMARY KEY REFERENCES revision CHECK (length(revision_uuid) = 36),
  z REAL
) STRICT;
CREATE TABLE production_meta (
  revision_uuid TEXT NOT NULL PRIMARY KEY REFERENCES revision CHECK (length(revision_uuid) = 36),
  reactor TEXT,
  note TEXT
) STRICT;
CREATE TABLE production_value (
  revision_uuid TEXT NOT NULL REFERENCES production_meta CHECK (length(revision_uuid) = 36),
  key TEXT NOT NULL,
  value REAL NOT NULL,
  error REAL NOT NULL,
  PRIMARY KEY (revision_uuid, key)
) STRICT;
CREATE TABLE level_production_value (
  revision_uuid TEXT NOT NULL PRIMARY KEY REFERENCES revision CHECK (length(revision_uuid) = 36),
  production_ref_uuid TEXT NOT NULL REFERENCES ref_object CHECK (length(production_ref_uuid) = 36),
  note TEXT
) STRICT;
CREATE TABLE chronology_dose (
  revision_uuid TEXT NOT NULL REFERENCES revision CHECK (length(revision_uuid) = 36),
  ordinal INTEGER NOT NULL,
  power REAL NOT NULL,
  start_utc TEXT NOT NULL CHECK (start_utc LIKE '____-__-__T__:__:__%Z'),
  end_utc TEXT NOT NULL CHECK (end_utc LIKE '____-__-__T__:__:__%Z'),
  PRIMARY KEY (revision_uuid, ordinal)
) STRICT;
CREATE TABLE detector_gain (
  revision_uuid TEXT NOT NULL REFERENCES revision CHECK (length(revision_uuid) = 36),
  detector TEXT NOT NULL,
  gain REAL NOT NULL,
  PRIMARY KEY (revision_uuid, detector)
) STRICT;
CREATE TABLE sensitivity_value (
  revision_uuid TEXT NOT NULL PRIMARY KEY REFERENCES revision CHECK (length(revision_uuid) = 36),
  sensitivity REAL NOT NULL,
  create_date_utc TEXT CHECK (create_date_utc LIKE '____-__-__T__:__:__%Z'),
  extra TEXT CHECK (json_valid(extra))
) STRICT;
CREATE TABLE holder_meta (
  revision_uuid TEXT NOT NULL PRIMARY KEY REFERENCES revision CHECK (length(revision_uuid) = 36),
  shape TEXT,
  radius REAL,
  has_hole_numbers INTEGER NOT NULL DEFAULT 0 CHECK (has_hole_numbers IN (0, 1))
) STRICT;
CREATE TABLE holder_hole (
  revision_uuid TEXT NOT NULL REFERENCES holder_meta CHECK (length(revision_uuid) = 36),
  ordinal INTEGER NOT NULL,
  hole_id TEXT NOT NULL,
  x REAL NOT NULL,
  y REAL NOT NULL,
  radius REAL,
  PRIMARY KEY (revision_uuid, ordinal)
) STRICT;
CREATE TABLE script_version (
  revision_uuid TEXT NOT NULL PRIMARY KEY REFERENCES revision CHECK (length(revision_uuid) = 36),
  script_sha BLOB NOT NULL REFERENCES script_text
) STRICT;
CREATE TABLE ref_document (
  revision_uuid TEXT NOT NULL PRIMARY KEY REFERENCES revision CHECK (length(revision_uuid) = 36),
  content_text TEXT,
  content_json TEXT CHECK (json_valid(content_json))
) STRICT;
CREATE TABLE derived_value (
  analysis_uuid TEXT NOT NULL REFERENCES analysis CHECK (length(analysis_uuid) = 36),
  fingerprint BLOB NOT NULL,
  name TEXT NOT NULL,
  value REAL,
  error REAL,
  units TEXT,
  reduction_version TEXT NOT NULL,
  computed_utc TEXT NOT NULL CHECK (computed_utc LIKE '____-__-__T__:__:__%Z'),
  PRIMARY KEY (analysis_uuid, fingerprint, name)
) STRICT;
CREATE INDEX derived_value_name_ix ON derived_value (name, value);
CREATE TABLE aliquot_lease (
  identifier_uuid TEXT NOT NULL REFERENCES identifier CHECK (length(identifier_uuid) = 36),
  aliquot INTEGER NOT NULL,
  client_uuid TEXT NOT NULL REFERENCES client CHECK (length(client_uuid) = 36),
  queue_uuid TEXT CHECK (length(queue_uuid) = 36),
  state TEXT NOT NULL CHECK (state IN ('leased','used','released','expired')),
  leased_utc TEXT NOT NULL CHECK (leased_utc LIKE '____-__-__T__:__:__%Z'),
  expires_utc TEXT CHECK (expires_utc LIKE '____-__-__T__:__:__%Z'),
  PRIMARY KEY (identifier_uuid, aliquot)
) STRICT;
CREATE INDEX aliquot_lease_client_ix ON aliquot_lease (client_uuid, state);
CREATE TABLE ingest_receipt (
  item_uuid TEXT NOT NULL PRIMARY KEY CHECK (length(item_uuid) = 36),
  client_uuid TEXT NOT NULL REFERENCES client CHECK (length(client_uuid) = 36),
  kind TEXT NOT NULL,
  payload_sha256 BLOB NOT NULL,
  change_seq INTEGER NOT NULL,
  ingested_utc TEXT NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ', 'now')) CHECK (ingested_utc LIKE '____-__-__T__:__:__%Z')
) STRICT;
CREATE TABLE change_counter (
  id INTEGER NOT NULL PRIMARY KEY CHECK (id = 1),
  seq INTEGER NOT NULL
) STRICT;
INSERT INTO change_counter VALUES (1, 0);
CREATE TABLE change_log (
  change_seq INTEGER NOT NULL PRIMARY KEY,
  committed_utc TEXT NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ', 'now')) CHECK (committed_utc LIKE '____-__-__T__:__:__%Z'),
  changeset_uuid TEXT REFERENCES changeset CHECK (length(changeset_uuid) = 36),
  client_uuid TEXT NOT NULL REFERENCES client CHECK (length(client_uuid) = 36),
  kind TEXT NOT NULL CHECK (kind IN ('changeset','ingest','blob_complete','catalog','lease'))
) STRICT;
CREATE TABLE change_entity (
  change_seq INTEGER NOT NULL REFERENCES change_log,
  entity_type TEXT NOT NULL,
  entity_uuid TEXT NOT NULL CHECK (length(entity_uuid) = 36),
  op TEXT NOT NULL DEFAULT 'upsert',
  detail TEXT CHECK (json_valid(detail)),
  PRIMARY KEY (change_seq, entity_type, entity_uuid)
) STRICT;
CREATE TABLE sync_conflict (
  uuid TEXT NOT NULL PRIMARY KEY CHECK (length(uuid) = 36),
  item_uuid TEXT NOT NULL CHECK (length(item_uuid) = 36),
  client_uuid TEXT NOT NULL REFERENCES client CHECK (length(client_uuid) = 36),
  author_user_uuid TEXT REFERENCES app_user CHECK (length(author_user_uuid) = 36),
  changeset_uuid TEXT NOT NULL CHECK (length(changeset_uuid) = 36),
  kind TEXT NOT NULL CHECK (kind IN ('cas','provisional_renumber')),
  heads TEXT NOT NULL CHECK (json_valid(heads)),
  winning_changeset_uuid TEXT REFERENCES changeset CHECK (length(winning_changeset_uuid) = 36),
  detail TEXT CHECK (json_valid(detail)),
  created_utc TEXT NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ', 'now')) CHECK (created_utc LIKE '____-__-__T__:__:__%Z'),
  resolution TEXT NOT NULL DEFAULT 'pending' CHECK (resolution IN ('pending','reapplied','discarded','accepted')),
  resolved_utc TEXT CHECK (resolved_utc LIKE '____-__-__T__:__:__%Z')
) STRICT;
CREATE INDEX change_entity_ix ON change_entity (entity_type, entity_uuid);
CREATE TABLE publish_target (
  uuid TEXT NOT NULL PRIMARY KEY CHECK (length(uuid) = 36),
  kind TEXT NOT NULL CHECK (kind IN ('project_repo','meta_repo')),
  repository_uuid TEXT REFERENCES repository CHECK (length(repository_uuid) = 36),
  remote_url TEXT,
  branch TEXT NOT NULL DEFAULT 'master',
  layout TEXT NOT NULL CHECK (json_valid(layout)),
  batch_policy TEXT NOT NULL,
  enabled INTEGER NOT NULL DEFAULT 1 CHECK (enabled IN (0, 1))
) STRICT;
CREATE TABLE publish_state (
  target_uuid TEXT NOT NULL PRIMARY KEY REFERENCES publish_target CHECK (length(target_uuid) = 36),
  published_through_seq INTEGER NOT NULL DEFAULT 0,
  pushed_through_seq INTEGER NOT NULL DEFAULT 0,
  last_commit_sha TEXT,
  last_push_utc TEXT CHECK (last_push_utc LIKE '____-__-__T__:__:__%Z'),
  state TEXT NOT NULL,
  attempts INTEGER NOT NULL DEFAULT 0,
  next_attempt_utc TEXT CHECK (next_attempt_utc LIKE '____-__-__T__:__:__%Z'),
  last_error TEXT
) STRICT;
CREATE TABLE publish_commit (
  target_uuid TEXT NOT NULL REFERENCES publish_target CHECK (length(target_uuid) = 36),
  commit_sha TEXT NOT NULL,
  first_seq INTEGER NOT NULL,
  last_seq INTEGER NOT NULL,
  changeset_uuids TEXT NOT NULL CHECK (json_valid(changeset_uuids)),
  published_utc TEXT NOT NULL CHECK (published_utc LIKE '____-__-__T__:__:__%Z'),
  PRIMARY KEY (target_uuid, commit_sha)
) STRICT;
CREATE TABLE published_file (
  target_uuid TEXT NOT NULL REFERENCES publish_target CHECK (length(target_uuid) = 36),
  path TEXT NOT NULL,
  subject_uuid TEXT CHECK (length(subject_uuid) = 36),
  kind TEXT,
  revision_uuid TEXT REFERENCES revision CHECK (length(revision_uuid) = 36),
  file_sha256 BLOB NOT NULL,
  commit_sha TEXT NOT NULL,
  PRIMARY KEY (target_uuid, path)
) STRICT;
CREATE TABLE import_provenance (
  entity_type TEXT NOT NULL,
  entity_uuid TEXT NOT NULL CHECK (length(entity_uuid) = 36),
  import_source_uuid TEXT NOT NULL REFERENCES import_source CHECK (length(import_source_uuid) = 36),
  path TEXT,
  commit_sha TEXT,
  git_blob_sha TEXT,
  git_author TEXT,
  git_utc TEXT CHECK (git_utc LIKE '____-__-__T__:__:__%Z'),
  PRIMARY KEY (entity_type, entity_uuid, import_source_uuid)
) STRICT;
CREATE INDEX import_provenance_commit_ix ON import_provenance (import_source_uuid, commit_sha);
CREATE TABLE import_conflict (
  uuid TEXT NOT NULL PRIMARY KEY CHECK (length(uuid) = 36),
  import_source_uuid TEXT REFERENCES import_source CHECK (length(import_source_uuid) = 36),
  path TEXT,
  entity_uuid TEXT CHECK (length(entity_uuid) = 36),
  conflict_kind TEXT NOT NULL,
  db_head_revision_uuid TEXT REFERENCES revision CHECK (length(db_head_revision_uuid) = 36),
  file_sha256 BLOB,
  detail TEXT CHECK (json_valid(detail)),
  resolution TEXT NOT NULL DEFAULT 'pending',
  resolved_by_user_uuid TEXT REFERENCES app_user CHECK (length(resolved_by_user_uuid) = 36),
  resolved_utc TEXT CHECK (resolved_utc LIKE '____-__-__T__:__:__%Z')
) STRICT;
