CREATE TRIGGER analysis_guard_update BEFORE UPDATE ON analysis WHEN NEW.uuid IS NOT OLD.uuid OR NEW.analysis_type IS NOT OLD.analysis_type OR NEW.experiment_type IS NOT OLD.experiment_type OR NEW.timestamp_utc IS NOT OLD.timestamp_utc OR NEW.time_zero_utc IS NOT OLD.time_zero_utc OR NEW.mass_spectrometer_uuid IS NOT OLD.mass_spectrometer_uuid OR NEW.extract_device_uuid IS NOT OLD.extract_device_uuid OR NEW.extract_value IS NOT OLD.extract_value OR NEW.extract_units IS NOT OLD.extract_units OR NEW.extract_duration IS NOT OLD.extract_duration OR NEW.cleanup_duration IS NOT OLD.cleanup_duration OR NEW.pre_cleanup IS NOT OLD.pre_cleanup OR NEW.post_cleanup IS NOT OLD.post_cleanup OR NEW.cryo_temperature IS NOT OLD.cryo_temperature OR NEW.weight IS NOT OLD.weight OR NEW.beam_diameter IS NOT OLD.beam_diameter OR NEW.pattern IS NOT OLD.pattern OR NEW.ramp_duration IS NOT OLD.ramp_duration OR NEW.ramp_rate IS NOT OLD.ramp_rate OR NEW.light_value IS NOT OLD.light_value OR NEW.tray IS NOT OLD.tray OR NEW.load_uuid IS NOT OLD.load_uuid OR NEW.load_holder IS NOT OLD.load_holder OR NEW.measurement_script_sha IS NOT OLD.measurement_script_sha OR NEW.extraction_script_sha IS NOT OLD.extraction_script_sha OR NEW.post_eq_script_sha IS NOT OLD.post_eq_script_sha OR NEW.post_meas_script_sha IS NOT OLD.post_meas_script_sha OR NEW.hops_script_sha IS NOT OLD.hops_script_sha OR NEW.spectrometer_snapshot_sha IS NOT OLD.spectrometer_snapshot_sha OR NEW.queue_uuid IS NOT OLD.queue_uuid OR NEW.run_index IS NOT OLD.run_index OR NEW.laboratory IS NOT OLD.laboratory OR NEW.instrument_name IS NOT OLD.instrument_name OR NEW.analyst_user_uuid IS NOT OLD.analyst_user_uuid OR NEW.acquisition_client_uuid IS NOT OLD.acquisition_client_uuid OR NEW.record_sha256 IS NOT OLD.record_sha256 OR NEW.record_schema_version IS NOT OLD.record_schema_version OR NEW.ingest_changeset_uuid IS NOT OLD.ingest_changeset_uuid OR NEW.created_utc IS NOT OLD.created_utc BEGIN SELECT RAISE(ABORT, 'pychron: analysis is append-only'); END;
CREATE TRIGGER analysis_no_delete BEFORE DELETE ON analysis BEGIN SELECT RAISE(ABORT, 'pychron: analysis is append-only'); END;
